var n=`1005-massaman-curry`;var t=`world-1005`;var i=`TH`;var s=`southeast-asia`;var r=4;var o=99;var m={en:`Massaman Curry`,ua:`Масаман-карі`};var u={en:`Massaman Curry is a dish from Thailand prepared with massaman curry paste, coconut cream, beef chuck, coconut milk. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Масаман-карі, страва кухні країни Таїланд, яку готують із таких продуктів: паста карі масаман, кокосові вершки, яловича лопатка, кокосове молоко. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 5 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 5 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:5,i:[[`massaman-curry-paste`,95,`g`],[`coconut-cream`,200,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 65 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 65 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:65,i:[[`beef-chuck`,700,`g`],[`coconut-milk`,420,`ml`],[`water`,220,`ml`],[`cardamom-pods`,4,`pcs`],[`ceylon-cinnamon`,1,`pcs`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`potato`,340,`g`],[`yellow-onion`,170,`g`],[`peanut`,75,`g`]]},{en:`Season the tender beef-and-potato curry with tamarind, palm sugar and fish sauce; massaman should be rich, mildly spicy and gently sweet–sour.`,ua:`Приправте ніжне карі з яловичиною та картоплею тамариндом, пальмовим цукром і рибним соусом; масаман має бути насиченим, злегка гострим та кисло-солодким.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`tamarind-concentrate`,28,`g`],[`palm-sugar`,35,`g`],[`fish-sauce`,35,`ml`]]}];var c={slug:n,id:t,country:`TH`,region:s,servings:4,minutes:99,title:m,text:u,steps:d};export{i as country,c as default,t as id,o as minutes,s as region,r as servings,n as slug,d as steps,u as text,m as title};